#ifndef CUBE_NET_HTTP_STATUS_H
#define CUBE_NET_HTTP_STATUS_H

/** http_status.h — HTTP status code to reason phrase map.
 *
 * Single source of truth for the reason text. Prefer
 * http_status_str(code) over whatever the server sent, so a missing
 * or localized reason phrase never leaks through.
 *
 * Covers RFC 9110 plus common extension codes.
 * Generated by tools/gen_status.py — do not edit by hand.
 */

const char *http_status_str(int code);

#endif /* CUBE_NET_HTTP_STATUS_H */
